-- +goose Up
-- +goose StatementBegin

-- Permission mode of the panel in the managed cluster, for agent and cloud
-- connectors (the ones whose RBAC is generated by the panel):
--  - scoped (default): the technical SA only reads what the panel shows and
--    writes go through the three impersonated groups with their ClusterRoles.
--    Every new resource type requires reapplying the RBAC.
--  - cluster-admin: the agent's SA (or the cloud identity) and the
--    bayplan:admins group are additionally bound to cluster-admin. "Install
--    and forget" for operators who prefer it; editors and readonly stay
--    scoped.
ALTER TABLE clusters ADD COLUMN rbac_mode TEXT NOT NULL DEFAULT 'scoped' CHECK (rbac_mode IN ('scoped', 'cluster-admin'));

-- +goose StatementEnd

-- +goose Down
-- +goose StatementBegin
ALTER TABLE clusters DROP COLUMN rbac_mode;
-- +goose StatementEnd
